source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # A full divider separates two equal-sized panels.
    divider = None
    for c in range(w):
        if c == w - 1 - c and all(grid[r][c] == grid[0][c] for r in range(h)):
            divider = ("col", c)
            break
    if divider is None:
        for r in range(h):
            if r == h - 1 - r and all(x == grid[r][0] for x in grid[r]):
                divider = ("row", r)
                break
    if divider is None:
        # General fallback: choose a uniform line that leaves equal panels.
        for c in range(w):
            if c == w - 1 - c and all(grid[r][c] == grid[0][c] for r in range(h)):
                divider = ("col", c)
                break
        for r in range(h):
            if divider is None and r == h - 1 - r and all(x == grid[r][0] for x in grid[r]):
                divider = ("row", r)
                break
    if divider is None:
        raise ValueError("no centered solid divider")
    axis, k = divider
    if axis == "col":
        a = [row[:k] for row in grid]
        b = [row[k+1:] for row in grid]
    else:
        a = grid[:k]
        b = grid[k+1:]
    def background(panel):
        return Counter(x for row in panel for x in row).most_common(1)[0][0]
    ba, bb = background(a), background(b)
    marked = Counter(x for row in a for x in row if x != ba)
    base = marked.most_common(1)[0][0] if marked else ba
    out = [[base for _ in row] for row in a]
    for r in range(len(a)):
        for c in range(len(a[0])):
            if a[r][c] != ba and b[r][c] != bb:
                out[r][c] = 3
    return out
'''
