source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = None
    for c in range(w):
        if c == w // 2 and all(grid[r][c] == grid[0][c] for r in range(h)):
            divider = ("col", c)
            break
    if divider is None:
        for r in range(h):
            if r == h // 2 and all(x == grid[r][0] for x in grid[r]):
                divider = ("row", r)
                break
    if divider is None:
        raise ValueError("no centered solid divider")
    axis, k = divider
    if axis == "col":
        a = [row[:k] for row in grid]
        b = [row[k+1:] for row in grid]
    else:
        a = grid[:k]
        b = grid[k+1:]
    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    # The panels share exactly one color; mark matching occurrences of that color.
    if len(common) != 1:
        raise ValueError(f"expected one shared color, got {common}")
    color = next(iter(common))
    out = [[color for _ in row] for row in a]
    for r in range(len(a)):
        for c in range(len(a[0])):
            if a[r][c] == color and b[r][c] == color:
                out[r][c] = 3
    return out
'''
